{"file": "src/packages/repl/src/screens/REPLView.tsx",
 "edits": [{"old": "          ...(shouldStorePlanForVerification && {
            pendingPlanVerification: {
              plan: initialMsg.message.planContent!,
              verificationStarted: false,
              verificationCompleted: false,
            },
          }),", "new": "          ...(shouldStorePlanForVerification
            ? {
                pendingPlanVerification: {
                  plan: initialMsg.message.planContent!,
                  verificationStarted: false,
                  verificationCompleted: false,
                },
              }
            : {}),"}],
 "patterns": [{"patron": "spread-of-and-chain-with-falsy-non-boolean",
